machine Cart {
  state {
    status : CartStatus = unopened
    items  : 0..2 = 0
    inv    : Ref<Inventory> = none
    pay    : Ref<Payments> = none
  }
  terminal status in { failed, cancelled, returned }

  action Open()
  action Add()
  action Checkout()
  action Cancel()
  action Return()
  action Reserved()
  action OutOfStock()
  action Charged()
  action Declined()

