import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

test('happy path: open, add, checkout, paid', async () => {
  const h: any = await createHost();
  assert.deepEqual(await h.open('a'), { ok: true });
  assert.equal((await h.open('a')).ok, false);
  assert.deepEqual(await h.cart('a'), { status: 'open', items: 0 });
  assert.equal(await h.cart('zz'), null);
  assert.equal((await h.add('zz')).ok, false);
  assert.equal(await h.cart('zz'), null);
  assert.equal((await h.checkout('a')).ok, false);
  await h.add('a'); await h.add('a');
  assert.equal((await h.add('a')).ok, false);
  assert.deepEqual(await h.checkout('a'), { ok: true });
  assert.deepEqual(await h.cart('a'), { status: 'reserving', items: 2 });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 1);
  assert.deepEqual({ ...msgs[0], id: undefined }, { id: undefined, from: 'a', to: 'inventory', action: 'Reserve', data: { from: 'a', qty: 2 } });
  await h.deliver(msgs[0].id);
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2 });
  const r = await h.inFlight();
  assert.deepEqual([r[0].from, r[0].to, r[0].action, r[0].data], ['inventory', 'a', 'Reserved', {}]);
  await h.deliver(r[0].id);
  assert.equal((await h.cart('a')).status, 'paying');
  const m2 = await h.inFlight();
  assert.equal(m2[0].action, 'Charge');
  assert.deepEqual(m2[0].data, { from: 'a', amount: 2 });
  assert.equal((await h.cancel('a')).ok, false);
  await h.deliverAll();
  assert.equal((await h.cart('a')).status, 'paid');
  assert.deepEqual(await h.payments(), { charged: 2, declining: false });
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2 });
  h.__dispose();
});

test('return a paid cart', async () => {
  const h: any = await createHost();
  await h.open('a'); await h.add('a'); await h.add('a');
  assert.equal((await h.returnCart('a')).ok, false);
  assert.equal((await h.returnCart('zz')).ok, false);
  await h.checkout('a'); await h.deliverAll();
  assert.deepEqual(await h.returnCart('a'), { ok: true });
  assert.deepEqual(await h.cart('a'), { status: 'returned', items: 2 });
  const msgs = (await h.inFlight()).map((m: any) => [m.from, m.to, m.action, m.data]).sort();
  assert.deepEqual(msgs, [['a', 'inventory', 'Release', { qty: 2 }], ['a', 'payments', 'Refund', { amount: 2 }]]);
  assert.equal((await h.returnCart('a')).ok, false);
  assert.equal((await h.cancel('a')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  assert.deepEqual(await h.payments(), { charged: 0, declining: false });
  h.__dispose();
});

test('out of stock and declined', async () => {
  const h: any = await createHost();
  await h.open('a'); await h.add('a'); await h.add('a');
  await h.open('b'); await h.add('b');
  await h.checkout('a'); await h.checkout('b');
  await h.deliverAll();
  const sa = (await h.cart('a')).status, sb = (await h.cart('b')).status;
  assert.deepEqual([sa, sb].sort(), ['failed', 'paid']);
  await h.open('c'); await h.add('c');
  assert.equal((await h.acceptCards()).ok, false);
  assert.deepEqual(await h.declineCards(), { ok: true });
  assert.deepEqual(await h.payments(), { charged: sa === 'paid' ? 2 : 1, declining: true });
  h.__dispose();
});

test('declined releases units; cancel while reserving releases', async () => {
  const h: any = await createHost();
  await h.declineCards();
  await h.open('a'); await h.add('a');
  await h.checkout('a');
  await h.deliverAll();
  assert.equal((await h.cart('a')).status, 'failed');
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  await h.acceptCards();
  await h.open('b'); await h.add('b'); await h.checkout('b');
  assert.deepEqual(await h.cancel('b'), { ok: true });
  assert.equal((await h.cart('b')).status, 'cancelling');
  await h.deliverAll();
  assert.equal((await h.cart('b')).status, 'cancelled');
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  assert.deepEqual(await h.payments(), { charged: 0, declining: false });
  await h.open('c');
  assert.deepEqual(await h.cancel('c'), { ok: true });
  assert.equal((await h.cart('c')).status, 'cancelled');
  assert.equal((await h.cancel('c')).ok, false);
  h.__dispose();
});

