type CartStatus = unopened | open | reserving | paying | paid | failed | cancelling | cancelled | returned | declined

machine Cart {
  state {
    status : CartStatus = unopened
    items  : 0..2 = 0
    inv    : Ref<Inventory> = none
    pay    : Ref<Payments> = none
  }
  terminal status in { failed, cancelled, returned }

  action Open()
  action Add()
  action Checkout()
  action Cancel()
  action Return()
  action Retry()
  action Abandon()
  action Reserved()
  action OutOfStock()
  action Charged()
  action Declined()

  on Open {
    require status is unopened else reject "cart-exists"
    status' = open
  }
  on Add {
    require status is open else reject "not-open"
    require items < 2 else reject "cart-full"
    items' = items + 1
  }
  on Checkout {
    require status is open else reject "not-open"
    require items > 0 else reject "empty-cart"
    status' = reserving
    send inv <- Reserve(from: self, qty: items)
  }
  on Cancel {
    require status in { open, reserving } else reject "cannot-cancel"
    if status is open { status' = cancelled } else { status' = cancelling }
  }
  on Return {
    require status is paid else reject "not-paid"
    status' = returned
    send pay <- Refund(amount: items)
    send inv <- Release(qty: items)
  }
  on Reserved {
    require status in { reserving, cancelling } else reject "not-reserving"
    if status is reserving {
      status' = paying
      send pay <- Charge(from: self, amount: items)
    } else {
      status' = cancelled
      send inv <- Release(qty: items)
    }
  }
  on OutOfStock {
    require status in { reserving, cancelling } else reject "not-reserving"
    if status is reserving { status' = failed } else { status' = cancelled }
  }
  on Charged {
    require status is paying else reject "not-paying"
    status' = paid
  }
  on Declined {
    require status is paying else reject "not-paying"
    status' = declined
  }
  on Retry {
    require status is declined else reject "not-declined"
    status' = paying
