test('payment timeout: late charge is refunded, late decline fails', async () => {
  const h: any = await createHost();
  await h.open('a'); await h.add('a'); await h.add('a');
  assert.equal((await h.paymentTimeout('a')).ok, false);
  await h.checkout('a');
  const [res] = await h.inFlight(); await h.deliver(res.id);
  const [rep] = await h.inFlight(); await h.deliver(rep.id);
  assert.equal((await h.cart('a')).status, 'paying');
  assert.deepEqual(await h.paymentTimeout('a'), { ok: true });
  assert.deepEqual(await h.cart('a'), { status: 'abandoning', items: 2 });
  for (const c of ['add', 'checkout', 'cancel', 'returnCart', 'retry', 'abandon', 'paymentTimeout']) assert.equal((await h[c]('a')).ok, false, c);
  const charge = (await h.inFlight()).find((m: any) => m.action === 'Charge');
  await h.deliver(charge.id);
  assert.deepEqual(await h.payments(), { charged: 2, declining: false });
  const charged = (await h.inFlight()).find((m: any) => m.action === 'Charged');
  await h.deliver(charged.id);
  assert.equal((await h.cart('a')).status, 'failed');
  const refund = (await h.inFlight()).find((m: any) => m.action === 'Refund');
  assert.deepEqual([refund.from, refund.to, refund.data], ['a', 'payments', { amount: 2 }]);
  await h.deliverAll();
  assert.deepEqual(await h.payments(), { charged: 0, declining: false });
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });

  await h.declineCards();
  await h.open('b'); await h.add('b'); await h.checkout('b');
  const [r2] = await h.inFlight(); await h.deliver(r2.id);
  const [p2] = await h.inFlight(); await h.deliver(p2.id);
  await h.paymentTimeout('b');
  await h.deliverAll();
  assert.equal((await h.cart('b')).status, 'failed');
  assert.deepEqual(await h.payments(), { charged: 0, declining: true });
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  h.__dispose();
});

