test('declined releases units; cancel while reserving releases', async () => {
  const h: any = await createHost();
  await h.declineCards();
  await h.open('a'); await h.add('a');
  await h.checkout('a');
  await h.deliverAll();
  assert.equal((await h.cart('a')).status, 'declined');
  assert.deepEqual(await h.stock(), { available: 1, reserved: 1 });
  for (const c of ['add', 'checkout', 'cancel', 'returnCart']) assert.equal((await h[c]('a')).ok, false, c);
  assert.equal((await h.retry('zz')).ok, false);
  assert.deepEqual(await h.retry('a'), { ok: true });
  assert.equal((await h.cart('a')).status, 'paying');
  assert.equal((await h.abandon('a')).ok, false);
  assert.equal((await h.retry('a')).ok, false);
  await h.deliverAll();
  assert.equal((await h.cart('a')).status, 'declined');
  assert.deepEqual(await h.abandon('a'), { ok: true });
  assert.equal((await h.cart('a')).status, 'failed');
  assert.equal((await h.retry('a')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  await h.acceptCards();
  await h.declineCards();
  await h.open('d'); await h.add('d'); await h.checkout('d'); await h.deliverAll();
  await h.acceptCards();
  assert.deepEqual(await h.retry('d'), { ok: true });
  await h.deliverAll();
  assert.equal((await h.cart('d')).status, 'paid');
  assert.deepEqual(await h.payments(), { charged: 1, declining: false });
  await h.returnCart('d'); await h.deliverAll();
  await h.open('b'); await h.add('b'); await h.checkout('b');
  assert.deepEqual(await h.cancel('b'), { ok: true });
  assert.equal((await h.cart('b')).status, 'cancelling');
  await h.deliverAll();
  assert.equal((await h.cart('b')).status, 'cancelled');
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  assert.deepEqual(await h.payments(), { charged: 0, declining: false });
  await h.open('c');
  assert.deepEqual(await h.cancel('c'), { ok: true });
  assert.equal((await h.cart('c')).status, 'cancelled');
  assert.equal((await h.cancel('c')).ok, false);
  h.__dispose();
});
